// Generated by `ml/train.py --level N` (outside git, like the data they come from):
// run training before bundling the app.
import level1 from '../../../ml/languages/aed/models/level-1/model.json';
import level2 from '../../../ml/languages/aed/models/level-2/model.json';

import { handLocation, LOCATION_VERSION, normalizeHand } from '@/dataset/features';
import type { RecordedHand } from '@/dataset/types';

import { Classifier, type ModelFile, type Prediction } from './classifier';

export type RecognitionLevel = 1 | 2;

const files: Record<RecognitionLevel, ModelFile> = {
  1: level1 as ModelFile,
  2: level2 as ModelFile,
};
const cache = new Map<RecognitionLevel, Classifier>();

export function classifierFor(level: RecognitionLevel): Classifier {
  let classifier = cache.get(level);
  if (classifier == null) {
    const file = files[level];
    const location = file.normalization.location;
    if (location != null && location.version !== LOCATION_VERSION) {
      throw new Error(
        `Model for level ${level} uses location v${location.version}, the app v${LOCATION_VERSION}. Retrain it.`,
      );
    }
    classifier = new Classifier(file);
    cache.set(level, classifier);
  }
  return classifier;
}

/**
 * Prepares one hand exactly like training did (ADR 0008) and classifies it. The
 * hand MediaPipe reports is used as the dominant hand: left hands are mirrored.
 * Null if the input can't be built (e.g. the model needs the face and there's none).
 */
export function classifyHand(
  classifier: Classifier,
  hand: RecordedHand,
  body: number[],
  imageWidth: number,
  imageHeight: number,
): Prediction | null {
  const shape = normalizeHand(hand.world, hand.handedness);
  if (shape == null) {
    return null;
  }
  let input = shape;
  if (classifier.usesLocation) {
    const location = handLocation(hand.landmarks, body, imageWidth, imageHeight, hand.handedness);
    if (location == null) {
      return null;
    }
    input = [...shape, ...location];
  }
  return classifier.predict(input);
}
